import time

RETRIES = 3
TIMEOUT_SECONDS = 5


def fetch_user(client, user_id):
    """Look a user up, retrying on a transient failure."""
    for attempt in range(RETRIES):
        try:
            return client.get(f"/users/{user_id}", timeout=TIMEOUT_SECONDS)
        except TimeoutError:
            time.sleep(2 ** attempt)
    raise TimeoutError("user lookup gave up")


def healthcheck(client):
    return client.get("/health", timeout=TIMEOUT_SECONDS).status_code == 200
